<div class="space-y-6"><section class="rounded-xl border border-slate-200 bg-white shadow-sm"><div class="flex items-center justify-between border-b border-slate-200 px-6 py-4"><div><h2 class="font-semibold text-slate-900">Household record</h2><p class="text-sm text-slate-500"><?= e($home['registration_number']) ?></p></div><a href="<?= e(APP_URL.'/families/'.(int)$home['family_id'].'/home/edit') ?>" class="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white">Edit</a></div><dl class="grid gap-6 p-6 sm:grid-cols-2 lg:grid-cols-3"><?php foreach([['Address',$home['address']],['PHM Area',$home['phm_area_name']],['MOH Area',$home['moh_name']],['Registered Date',$home['registered_date']],['Status',$home['status']],['Remarks',$home['remarks']??'None recorded']] as [$l,$v]): ?><div><dt class="text-xs font-semibold uppercase text-slate-400"><?= e($l) ?></dt><dd class="mt-1 text-sm text-slate-800"><?= e($v) ?></dd></div><?php endforeach; ?></dl></section><div class="rounded-lg border border-blue-200 bg-blue-50 p-4 text-sm text-blue-800">The current database stores household address, area, status and remarks. Water, sanitation and housing-condition fields require additional schema columns before they can be recorded reliably.</div></div>
